/**
 * Build the static demo into demo-static/public.
 *
 * Usage: node demo-static/build.mjs   (or: bun demo-static/build.mjs)
 *
 * The output is a plain static site:
 *   - the real shell, CSS, JS and icons copied from src/public
 *   - the 28 widget folders copied from data/widgets
 *   - seed.json (generated by tools/generate-data.mjs) in /site-data
 *   - the IndexedDB engine, shell shim and widget bridge in /demo
 *
 * Nothing here talks to a server, a database or a model.
 */

import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..');
const out = join(here, 'public');

const SKIP_WIDGET_DIRS = new Set(['.backups', '.sessions', '.opencode', 'uploads', 'node_modules']);

if (!existsSync(join(here, 'data', 'seed.json'))) {
  console.error('Missing demo-static/data/seed.json — run `bun demo-static/tools/generate-data.mjs` first.');
  process.exit(1);
}

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });

// --- Static shell ---
cpSync(join(repoRoot, 'src', 'public', 'static'), join(out, 'static'), { recursive: true });
cpSync(join(repoRoot, 'src', 'public', 'manifest.json'), join(out, 'manifest.json'));

// Keep app.js happy and purge any cache left by an older deployment.
writeFileSync(
  join(out, 'sw.js'),
  `// Static demo: no offline cache.
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});
`,
);

// --- IndexedDB engine + shims ---
mkdirSync(join(out, 'demo'), { recursive: true });
for (const file of ['engine.js', 'shell.js', 'widget-bridge.js']) {
  cpSync(join(here, 'src', file), join(out, 'demo', file));
}

// --- Seed data ---
mkdirSync(join(out, 'site-data'), { recursive: true });
cpSync(join(here, 'data', 'seed.json'), join(out, 'site-data', 'seed.json'));

// --- Shell HTML ---
let html = readFileSync(join(repoRoot, 'src', 'public', 'index.html'), 'utf8');
html = html.replace('<html lang="fr">', '<html lang="en">');
html = html.replace('<title>Dashboard</title>', '<title>Dashboard — Static demo</title>');
html = html.replace('<head>', '<head>\n  <script>window.DEMO_MODE = true;</script>');
html = html.replace(
  '<script type="module" src="/static/js/app.js',
  '<script type="module" src="/demo/shell.js?v=2"></script>\n  <script type="module" src="/static/js/app.js',
);
// The static build cannot execute scripts, so drop the Scripts entry point
// from the markup instead of only hiding it after the shell loads.
html = html.replace(/\s*<div class="sidebar-footer">[\s\S]*?<\/div>(?=\s*<\/aside>)/, '');
writeFileSync(join(out, 'index.html'), html);

// --- Widgets ---
const widgetsRoot = join(repoRoot, 'data', 'widgets');
const widgets = readdirSync(widgetsRoot, { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && !SKIP_WIDGET_DIRS.has(entry.name))
  .map((entry) => entry.name)
  .filter((name) => existsSync(join(widgetsRoot, name, 'index.html')));

for (const id of widgets) {
  const source = join(widgetsRoot, id);
  const target = join(out, 'widgets', id);
  cpSync(source, target, {
    recursive: true,
    filter: (path) => !SKIP_WIDGET_DIRS.has(path.split(/[\\/]/).pop()),
  });

  const indexPath = join(target, 'index.html');
  let widgetHtml = readFileSync(indexPath, 'utf8');
  if (!widgetHtml.includes('widget-bridge.js')) {
    if (/<head[^>]*>/i.test(widgetHtml)) {
      widgetHtml = widgetHtml.replace(/(<head[^>]*>)/i, '$1\n  <script src="/demo/widget-bridge.js"></script>');
    } else {
      widgetHtml = `<script src="/demo/widget-bridge.js"></script>\n${widgetHtml}`;
    }
    writeFileSync(indexPath, widgetHtml);
  }
}

const size = (path) => {
  const stats = existsSync(path) ? readFileSync(path).length : 0;
  return `${(stats / 1024).toFixed(1)} kB`;
};

console.log(`Static demo built in ${out}`);
console.log(`  index.html     ${size(join(out, 'index.html'))}`);
console.log(`  seed.json      ${size(join(out, 'site-data', 'seed.json'))}`);
console.log(`  widgets        ${widgets.length}`);
